// HubSpot on the business's private app token: every operation in HubSpot's published API that such a token can call.
// actions.json is generated by `bun scripts/openapi-actions.ts hubspot`. HubSpot's webhooks can only be set on a
// developer app, so its triggers are polled (polls/hubspot.ts).
import { z } from "zod";
import { AppsError } from "../../types";
import type { OwnApp } from "../index";
import { type Api, call, rest, specActions } from "../openapi";

const api: Api = {
  name: "HubSpot",
  base: "https://api.hubapi.com",
  tokenHelp: "HubSpot → Settings → Integrations → Private Apps",
};

export const hubspot: OwnApp = {
  app: "hubspot",
  name: "HubSpot",
  logo: "/logos/hubspot.svg",
  keyField: {
    label: "Private app access token",
    help: "In HubSpot: Settings → Integrations → Private Apps (on newer accounts, Development → Legacy Apps) → Create a private app. Under Scopes tick what Emplio should reach: at least crm.objects.contacts, crm.objects.companies, crm.objects.deals and tickets, read and write. Then Create app and copy the access token.",
    placeholder: "pat-na1-...",
  },
  async check(key) {
    try {
      const me = (await call(api, key, { method: "GET", path: "/account-info/v3/details", query: [], headers: [] }, {})) as { portalId?: number; uiDomain?: string };
      return me.portalId ? `HubSpot account ${me.portalId}` : undefined;
    } catch (error) {
      // a token without the account-info scope is still a good token
      if (error instanceof AppsError && !error.expired && error.message.endsWith("(403)")) return;
      throw error;
    }
  },
  actions: {
    ...(await specActions(new URL("./actions.json", import.meta.url), api)),
    // HubSpot's older APIs, still running but not in its published catalog: what the current ones have no equal for
    enroll_contact_in_workflow: rest(api, "POST", "/automation/v2/workflows/{workflowId}/enrollments/contacts/{email}", "Add a contact to a HubSpot workflow, by the contact's email.", z.object({ workflowId: z.string().describe("The workflow's id (see get_workflows)"), email: z.string().describe("The contact's email address") })),
    get_contact_workflow_enrollments: rest(api, "GET", "/automation/v2/workflows/enrollments/contacts/{vid}", "See which workflows a contact is enrolled in.", z.object({ vid: z.string().describe("The contact's id") })),
    list_email_events: rest(api, "GET", "/email/public/v1/events", "List what happened to marketing emails (sent, opened, clicked, bounced...), newest first.", z.object({ recipient: z.string().optional().describe("Only events for this email address"), campaignId: z.string().optional().describe("Only events of this email campaign"), eventType: z.string().optional().describe("Only this type, like OPEN, CLICK, DELIVERED or BOUNCE"), startTimestamp: z.number().optional().describe("Earliest time, in milliseconds since 1970"), endTimestamp: z.number().optional().describe("Latest time, in milliseconds since 1970"), limit: z.number().optional().describe("How many to return, at most 1000"), offset: z.string().optional().describe("The offset from the previous answer, for the next page") })),
    list_email_campaigns: rest(api, "GET", "/email/public/v1/campaigns/by-id", "List marketing email campaigns with their ids.", z.object({ limit: z.number().optional().describe("How many to return, at most 1000"), offset: z.string().optional().describe("The offset from the previous answer, for the next page") })),
    list_form_submissions: rest(api, "GET", "/form-integrations/v1/submissions/forms/{formId}", "List what people submitted through a HubSpot form, newest first.", z.object({ formId: z.string().describe("The form's id (see get_marketing_forms)"), limit: z.number().optional().describe("How many to return, at most 50"), after: z.string().optional().describe("The paging token from the previous answer") })),
    remove_contact_secondary_email: rest(api, "DELETE", "/contacts/v1/secondary-email/{vid}/email/{email}", "Remove one of a contact's extra email addresses.", z.object({ vid: z.string().describe("The contact's id"), email: z.string().describe("The email address to remove") })),
    list_call_dispositions: rest(api, "GET", "/calling/v1/dispositions", "List the outcomes a logged call can have (connected, no answer...), with their ids.", z.object({})),
  },
};
